"use client";

import { ReactNode } from "react";
import Sidebar from "@/app/components/Sidebar";

export default function DoadorLayout({
  children,
}: {
  children: ReactNode;
}) {
  return (
    <div className="flex min-h-screen w-full">
      <Sidebar />

      <main className="flex-1 bg-gray-50 overflow-x-hidden">
        <div className="p-6">
          {children}
        </div>
      </main>
    </div>
  );
}
